import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;
import java.util.regex.Pattern;
import org.springframework.stereotype.Component;

@Component
public class OrderPricing {

    private static final double VAT_PERCENT = 23.0;

    /** Accepts "12", "12.5", "12.50"; at most two decimals; no sign, no exponent. */
    private static final Pattern PERCENT = Pattern.compile("(\\d{1,3})(?:\\.(\\d{1,2}))?");

    public Money withVat(Money net) {
        double gross = net.minorUnits() * (100 + VAT_PERCENT) / 100;
        return new Money(Math.round(gross), net.currency());
    }

    /** Parses a percentage from text into whole basis points (12.5 becomes 1250). */
    public long basisPoints(String percent) {
        var matcher = PERCENT.matcher(null == percent ? "" : percent.trim());
        if (!matcher.matches()) {
            throw new ShopProblem("invalid-discount", "Not a percentage: " + percent);
        }
        long whole = Long.parseLong(matcher.group(1));
        String fraction = null == matcher.group(2) ? "" : matcher.group(2);
        long hundredths = fraction.isEmpty() ? 0 : Long.parseLong(fraction) * (fraction.length() == 1 ? 10 : 1);
        long basisPoints = whole * 100 + hundredths;
        if (basisPoints > 10_000) {
            throw new ShopProblem("invalid-discount", "Discount above 100%: " + percent);
        }
        return basisPoints;
    }

    /** The discount on a total, rounded half up to a whole minor unit. */
    public Money discount(Money total, long basisPoints) {
        long minorUnits = total.minorUnits() * basisPoints;
        return new Money((minorUnits + 5_000) / 10_000, total.currency());
    }
}
}

