import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.platform.ShopProblem;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class OrderDiscountTest {

    @Test
    void aDiscountLowersTheTotalAndRoundsHalfUp() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(100), Instant.parse("2026-10-01T10:00:00Z"));

            orders.applyDiscount(id, "0.5");

            assertEquals(Money.pln(99), orders.summary(id).total());
        }
    }

    @Test
    void aPercentageWithOneDecimalIsApplied() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(10_000), Instant.parse("2026-10-01T10:00:00Z"));

            orders.applyDiscount(id, " 12.5 ");

            assertEquals(Money.pln(8_750), orders.summary(id).total());
        }
    }

    @Test
    void aMalformedPercentageIsRejected() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(10_000), Instant.parse("2026-10-01T10:00:00Z"));

            for (String bad : new String[] {"", "abc", "-5", "1e2", "12,5", "100.01", "1.234"}) {
                ShopProblem problem = assertThrows(ShopProblem.class, () -> orders.applyDiscount(id, bad));
                assertEquals("invalid-discount", problem.code());
            }
            assertEquals(Money.pln(10_000), orders.summary(id).total());
        }
    }
}
}
